insert into public.sections (page_id, key, type, tone, data, position) select id, 'hero', 'heroCentered', NULL, '{"eyebrow":"Monthly SEO Packages","heading":"The Prices Are on This Page","body":"Six monthly packages across two service lines, with what each one includes and what it costs. Nothing here is behind a call, because a price you have to ask for is a price that changes depending on who is asking."}'::jsonb, 0 from public.pages where slug = '/monthly-seo-packages';
insert into public.sections (page_id, key, type, tone, data, position) select id, 'path', 'cardGrid', 'surface', '{"variant":"cards","columns":2,"eyebrow":"Start Here","heading":"Two Paths, Sorted by Reach","body":"Which one fits comes down to where a business competes, not how large it is.","cards":[{"title":"Local SEO","icon":"map-pin","meta":"From $875 a month","body":"For businesses competing for customers in a defined area, however many locations they run inside it.","cta":{"label":"View Local SEO Packages","href":"#local"}},{"title":"Traditional SEO","icon":"globe","meta":"From $2,295 a month","body":"For businesses competing across multiple markets, multiple service lines, or genuinely competitive search.","cta":{"label":"View Traditional SEO Packages","href":"#traditional"}}]}'::jsonb, 1 from public.pages where slug = '/monthly-seo-packages';
insert into public.sections (page_id, key, type, tone, data, position) select id, 'local', 'pricingCards', 'white', '{"eyebrow":"Local SEO","heading":"Local SEO Packages","body":"Three tiers, sized by how much ground you are competing for.","packageIds":["local-neighborhood","local-citywide","local-metro"]}'::jsonb, 2 from public.pages where slug = '/monthly-seo-packages';
insert into public.sections (page_id, key, type, tone, data, position) select id, 'local-custom', 'fullWidthText', 'white', '{"heading":"Bigger Than Metro?","body":"If the scope is bigger or more involved than what is here, JMC will look at it and put together a quote. That is still a Local engagement, however many locations are involved.","cta":{"label":"Request a Visibility Review","href":"/contact"}}'::jsonb, 3 from public.pages where slug = '/monthly-seo-packages';
insert into public.sections (page_id, key, type, tone, data, position) select id, 'traditional', 'pricingCards', 'surface', '{"eyebrow":"Traditional SEO","heading":"Traditional SEO Packages","body":"Three tiers, sized by footprint rather than by headcount.","packageIds":["traditional-regional","traditional-national","traditional-national-plus"],"cta":{"label":"Request a Visibility Review","href":"/contact"}}'::jsonb, 4 from public.pages where slug = '/monthly-seo-packages';
insert into public.sections (page_id, key, type, tone, data, position) select id, 'included', 'cardGrid', 'white', '{"variant":"compact","columns":3,"eyebrow":"Every Tier","heading":"Included in Every Package","body":"Tiers differ by volume, not by what is included.","groupLabels":[{"at":0,"label":"Local SEO, all tiers"},{"at":6,"label":"Traditional SEO, all tiers"}],"cards":[{"title":"SEO Strategy & Roadmap","icon":"compass","body":"A plan for the quarter, with the reasoning behind the order."},{"title":"Content & On-Page Optimization","icon":"pencil","body":"Service pages, titles, descriptions and page structure."},{"title":"Technical Monitoring","icon":"gauge","body":"Crawling, indexing and site health watched month to month."},{"title":"Detailed Monthly Reporting","icon":"bar-chart","body":"What was tracked, what moved, and what did not."},{"title":"Monthly Project Recap","icon":"message-square","body":"Delivered by Loom or a video call, with room to ask questions."},{"title":"Review Management","icon":"star","body":"Requests sent to real customers, and replies to what arrives."},{"title":"SEO Strategy & Roadmap","icon":"compass","body":"The same plan, applied across markets rather than an area."},{"title":"Strategic SEO Pages","icon":"file-text","body":"Pages built for specific searches, produced to a schedule."},{"title":"Technical Monitoring","icon":"gauge","body":"Issues flagged as they appear, not found in an annual audit."},{"title":"Reporting & Monthly Recap","icon":"bar-chart","body":"Dashboard reporting alongside the recap, in both cases explained."},{"title":"Authority-Building Recommendations","icon":"network","body":"Advice on what would strengthen authority. Recommendations, not link placements."}]}'::jsonb, 5 from public.pages where slug = '/monthly-seo-packages';
insert into public.sections (page_id, key, type, tone, data, position) select id, 'onboarding', 'featureSplit', 'surface', '{"align":"left","eyebrow":"The One-Time Fee","heading":"What Onboarding Covers","body":"Every tier carries a one-time onboarding fee, from $349 to $1,295 depending on the package. It pays for the work that has to happen once before the monthly work means anything: nothing built on an unaudited foundation is worth reporting on.\n\nThe two scopes are genuinely different rather than one generic setup with different price tags, which is why they are listed separately below. A Launch Sprint can waive this fee entirely, which the next section sets out.","tableHeadings":["Lane","Onboarding covers"],"tableRows":[{"cells":["Local SEO","Audit, setup, tracking, foundational optimization, and local visibility setup"]},{"cells":["Traditional SEO","Audit, setup, tracking, foundational optimization, and roadmap development"]}],"groups":[],"cta":{"label":"View Launch Sprints","href":"/launch-sprints"}}'::jsonb, 6 from public.pages where slug = '/monthly-seo-packages';
insert into public.sections (page_id, key, type, tone, data, position) select id, 'sprint-waiver', 'waiverMatrix', 'white', '{"eyebrow":"Another Way In","heading":"Start With a Launch Sprint","body":"A sprint is the onboarding work done standalone, with a roadmap attached. That is why the waiver exists rather than being a discount: it is close to the same job, bought once, with no monthly commitment behind it.","sprintHeading":"Sprint","priceHeading":"One-time","waivesHeading":"Waives onboarding on","rows":[{"sprint":"Neighborhood Launch Sprint","price":"$799","waives":"Neighborhood, Citywide, or Metro"},{"sprint":"Regional Launch Sprint","price":"$1,495","waives":"Regional"},{"sprint":"National Launch Sprint","price":"$2,295","waives":"National or National+"}],"condition":"Monthly service must begin within 30 calendar days of sprint completion.","cta":{"label":"View Launch Sprints","href":"/launch-sprints"}}'::jsonb, 7 from public.pages where slug = '/monthly-seo-packages';
insert into public.sections (page_id, key, type, tone, data, position) select id, 'monthly-recap', 'reportingBlock', 'surface', '{"eyebrow":"Reporting","heading":"The Monthly Recap","body":"Included in every package in both lanes, at every tier.","did":"The specific work completed that month, named task by task.","why":"Why that work was the priority ahead of everything else in the queue.","changed":"What moved, reported honestly, including the months where little did.","next":"Next month''s priorities, so nothing in the following recap is a surprise.","cta":{"label":"See How JMC Reports SEO Progress","href":"/seo-reporting"}}'::jsonb, 8 from public.pages where slug = '/monthly-seo-packages';
insert into public.sections (page_id, key, type, tone, data, position) select id, 'faq', 'faq', 'white', '{"eyebrow":"Questions","heading":"Pricing Questions","items":[{"question":"Why a 12-month term?","answer":"Because SEO compounds and a short engagement cannot show what a full one can. Most of the foundational work lands in the first quarter and most of the return on it arrives later, so a three-month contract would mean paying for the setup and leaving before the benefit. The term applies to all six monthly tiers in both lanes."},{"question":"What happens after 12 months?","answer":"It runs month to month from then on, for as long as you want it to, and either side can end it with 30 days written notice. There is no second term and no automatic re-commitment."},{"question":"What does the onboarding fee cover?","answer":"On Local: the audit, tracking setup, foundational optimization and the local visibility setup, meaning profile, categories, services, citations and the grid baseline. On Traditional: the audit, tracking setup, foundational optimization and roadmap development. A Launch Sprint can waive it entirely if monthly service begins within 30 days of the sprint finishing."},{"question":"Can tiers be changed later?","answer":"Upgrades happen any time. The deliverables adjust from the next cycle and there is no additional onboarding fee. Downgrades take effect at renewal rather than mid-term."},{"question":"Which lane fits?","answer":"Reach decides it, not size. A business competing for customers in a defined area is Local, however many locations it runs there. A business competing across markets, service lines or competitive search is Traditional. Both service pages set out the difference in more detail."},{"question":"Does this include blog content?","answer":"Yes. Strategic SEO Pages covers all written SEO content, blog posts included. Early phases usually prioritise local and industry pages first, simply because blog content needs somewhere to point before it does much good."},{"question":"What is not included?","answer":"Paid advertising, web design and development, social media posting, and link building. Authority building is covered as recommendations rather than as placements bought on your behalf."},{"question":"Is there anything without a term?","answer":"Launch Sprints. One-time, completed within 30 days, no term and no renewal, ending with a roadmap that is yours whatever you decide next."},{"question":"Can Local and Traditional be combined?","answer":"Yes, as a custom plan. It is usually scoped from the Local deliverable side with the Traditional work layered on, and it needs a conversation rather than a package number."},{"question":"What if none of these fit?","answer":"Larger or more involved scopes get a custom quote. That is a real answer rather than a polite one: several kinds of engagement genuinely do not fit into three tiers."}],"cta":{"label":"Request a Visibility Review","href":"/contact"}}'::jsonb, 9 from public.pages where slug = '/monthly-seo-packages';
insert into public.sections (page_id, key, type, tone, data, position) select id, 'final-cta', 'finalCta', NULL, '{"heading":"Not Sure Which One Fits?","body":"A visibility review covers where you appear now, what is holding it back, and which package or sprint actually matches the problem.","primaryCta":{"label":"Request a Visibility Review","href":"/contact"},"secondaryCta":{"label":"View Launch Sprints","href":"/launch-sprints"}}'::jsonb, 10 from public.pages where slug = '/monthly-seo-packages';
insert into public.sections (page_id, key, type, tone, data, position) select id, 'hero', 'heroSplit', NULL, '{"eyebrow":"Launch Sprints","heading":"A Fixed Scope, Finished in Thirty Days","body":"A Launch Sprint is a single engagement with a defined start, a defined end, and a written list of everything included. There is no term, no renewal, and no obligation to continue afterwards.","primaryCta":{"label":"Request a Sprint Consultation","href":"/contact?type=sprint"},"secondaryCta":{"label":"View Monthly SEO Packages","href":"/monthly-seo-packages"},"showcase":[{"kind":"roadmap","label":"Thirty days","title":"The Sprint","items":["Audit","Implementation","Handoff","30-Day Action Roadmap"]},{"kind":"coverage","label":"Three sprints","title":"Sized by Reach","items":["Neighborhood","Regional","National"]}]}'::jsonb, 0 from public.pages where slug = '/launch-sprints';
insert into public.sections (page_id, key, type, tone, data, position) select id, 'what-a-sprint-is', 'cardGrid', 'surface', '{"variant":"cards","columns":3,"eyebrow":"The Shape of It","heading":"What a Sprint Is","body":"Three things, and they are the whole of the commitment.","cards":[{"title":"One-Time","icon":"rocket","body":"A single engagement. No term, no renewal, and no ongoing invoice arriving next month."},{"title":"Thirty Days","icon":"calendar","body":"A defined window with a defined end. The work is completed inside it rather than running until somebody stops it."},{"title":"Fixed Scope","icon":"list-checks","body":"The deliverable list is the whole list, agreed before anything starts. What is on it gets done, and it is written down."}]}'::jsonb, 1 from public.pages where slug = '/launch-sprints';
insert into public.sections (page_id, key, type, tone, data, position) select id, 'where-it-ends', 'cardGrid', 'white', '{"variant":"numbered","columns":3,"eyebrow":"The Boundary","heading":"Where a Sprint Ends","body":"Being precise about where a fixed-scope engagement stops is the same principle as reporting honestly. It just applies to scope instead.","cards":[{"title":"The List Is the Scope","body":"Everything included is written down before the work begins. Anything outside it is quoted separately rather than absorbed quietly or dropped without mention."},{"title":"Thirty Days, Then Done","body":"The window closes. There is no rollover into an open-ended timeline and no month four that nobody agreed to."},{"title":"A Foundation, Not a Campaign","body":"A sprint builds the base and hands over a roadmap. Ongoing growth is a separate decision, made afterwards with the roadmap in hand."}]}'::jsonb, 2 from public.pages where slug = '/launch-sprints';
insert into public.sections (page_id, key, type, tone, data, position) select id, 'sprints', 'pricingCards', 'surface', '{"eyebrow":"The Three Sprints","heading":"Three Sprints, Sized by Reach","body":"Neighborhood is local work. Regional and National are technical and on-page work across markets. That is a difference in kind rather than in size, so none of the three is a step up from another.","packageIds":["sprint-neighborhood","sprint-regional","sprint-national"]}'::jsonb, 3 from public.pages where slug = '/launch-sprints';
insert into public.sections (page_id, key, type, tone, data, position) select id, 'process', 'processSteps', 'white', '{"eyebrow":"Inside the Window","heading":"What Happens During the Sprint","steps":[{"title":"Audit","body":"The current foundation is reviewed end to end, the priority issues are identified and ranked, and the first fixes are confirmed with you before any of them happen."},{"title":"Implementation","body":"The included setup and optimization work is completed inside the agreed scope. Anything found along the way that sits outside it is flagged and quoted rather than absorbed."},{"title":"Handoff","body":"A clear roadmap with next-step recommendations in priority order, and a clean path into monthly service if that is what you decide to do."}]}'::jsonb, 4 from public.pages where slug = '/launch-sprints';
insert into public.sections (page_id, key, type, tone, data, position) select id, 'waiver', 'waiverMatrix', 'surface', '{"eyebrow":"Continuing On","heading":"Continuing Into Monthly Service","body":"The sprint deliverables and the onboarding work on a monthly package are close to the same job. That is why the waiver exists: a sprint is the onboarding done standalone, with a roadmap attached.","sprintHeading":"Sprint","waivesHeading":"Waives onboarding on","rows":[{"sprint":"Neighborhood","waives":"Neighborhood, Citywide, or Metro"},{"sprint":"Regional","waives":"Regional"},{"sprint":"National","waives":"National or National+"}],"condition":"Monthly service must begin within 30 calendar days of sprint completion.","cta":{"label":"View Monthly SEO Packages","href":"/monthly-seo-packages"}}'::jsonb, 5 from public.pages where slug = '/launch-sprints';
insert into public.sections (page_id, key, type, tone, data, position) select id, 'roadmap', 'cardGrid', 'white', '{"variant":"cards","columns":4,"emphasis":true,"eyebrow":"The Deliverable","heading":"What You Walk Away With","body":"The 30-Day Action Roadmap is the thing the sprint is actually for. Everything else is the work that makes it worth reading.","cards":[{"title":"Priority Findings","icon":"search","body":"What is holding visibility back, ranked by impact rather than listed in the order it was found."},{"title":"Completed Work","icon":"clipboard-check","body":"Everything done during the sprint, itemised, so there is no gap between what was paid for and what is visible."},{"title":"Recommended Next Steps","icon":"compass","body":"What to do next, in order, with the reasoning behind the order rather than just the list."},{"title":"A Clear Path Forward","icon":"target","body":"Whether that means monthly service or handling the roadmap internally. Both are real answers, and the roadmap is written to work either way."}],"cta":{"label":"See How JMC Reports SEO Progress","href":"/seo-reporting"}}'::jsonb, 6 from public.pages where slug = '/launch-sprints';
insert into public.sections (page_id, key, type, tone, data, position) select id, 'faq', 'faq', 'surface', '{"eyebrow":"Questions","heading":"Sprint Questions","items":[{"question":"Is there any ongoing commitment?","answer":"None. A sprint is a one-time engagement with no term and no auto-renewal. When the 30 days are up, the work is delivered and the arrangement is over unless you decide otherwise."},{"question":"What happens after the 30 days?","answer":"The 30-Day Action Roadmap is handed over, along with everything completed during the sprint. Continuing into monthly service is optional and is a separate decision."},{"question":"How does the onboarding waiver work?","answer":"If monthly service starts within 30 calendar days of the sprint finishing, the onboarding fee on the matching package is waived. The Neighborhood sprint covers Neighborhood, Citywide or Metro; Regional covers Regional; National covers National or National+."},{"question":"Which sprint fits?","answer":"Neighborhood is local work, including the Google Business Profile, citations and a local grid baseline. Regional and National are technical and on-page work across multiple markets. The difference is what a business competes in, not how large it is."},{"question":"Can the roadmap be handled internally?","answer":"Yes. It is written to be actionable by whoever ends up doing it, and plenty of businesses take it and run it themselves. That is a legitimate outcome rather than a failed one."},{"question":"Is a sprint required before monthly service?","answer":"No. It is one route in, not a gate. Monthly packages can start directly, with the standard onboarding fee."}],"cta":{"label":"Request a Sprint Consultation","href":"/contact?type=sprint"}}'::jsonb, 7 from public.pages where slug = '/launch-sprints';
insert into public.sections (page_id, key, type, tone, data, position) select id, 'final-cta', 'finalCta', NULL, '{"heading":"Start With a Sprint","body":"A fixed scope, thirty days, and a roadmap at the end of it that is yours whatever you decide to do next.","primaryCta":{"label":"Request a Sprint Consultation","href":"/contact?type=sprint"},"secondaryCta":{"label":"View Monthly SEO Packages","href":"/monthly-seo-packages"}}'::jsonb, 8 from public.pages where slug = '/launch-sprints';
insert into public.sections (page_id, key, type, tone, data, position) select id, 'hero', 'heroSplit', NULL, '{"eyebrow":"Google Business Profile Optimization","heading":"Your Google Business Profile Is Doing More Work Than Your Website","body":"For most local searches the profile is what people see, read and act on, often without ever opening a website. Getting it right is the fastest visibility work available to a local business.","primaryCta":{"label":"Get a Free Visibility Audit","href":"#free-audit"},"secondaryCta":{"label":"Explore Local SEO","href":"/local-seo-services"},"showcase":[{"kind":"coverage","label":"What gets worked","title":"The Profile Itself","items":["Categories and services","Business information","Photos and posts","Reviews and replies"]},{"kind":"channels","label":"Where it shows","title":"Local Surfaces","items":["Map results","Local search","Profile panel"]}]}'::jsonb, 0 from public.pages where slug = '/google-business-profile-optimization';
insert into public.sections (page_id, key, type, tone, data, position) select id, 'what-it-affects', 'cardGrid', 'surface', '{"variant":"cards","columns":3,"eyebrow":"Why It Matters","heading":"What the Profile Actually Affects","body":"Three things, none of which the website controls.","cards":[{"title":"Map Results","icon":"map-pin","body":"Where the business appears when somebody searches nearby. The profile is what is being ranked in that result, not the website behind it."},{"title":"First Impressions","icon":"storefront","body":"Hours, photos, services and reviews are read directly in the results. For a lot of searches that is the whole of what someone sees before deciding."},{"title":"Direct Actions","icon":"phone","body":"Calls, direction requests and website clicks all happen from the profile itself. A weak one loses those before a visit ever starts."}]}'::jsonb, 1 from public.pages where slug = '/google-business-profile-optimization';
insert into public.sections (page_id, key, type, tone, data, position) select id, 'problems', 'cardGrid', 'white', '{"variant":"compact","columns":3,"eyebrow":"Sound Familiar","heading":"Common Profile Problems","body":"Most profiles have at least two of these. Several of them take minutes to fix and have been costing visibility for years.","cards":[{"title":"Incomplete Categories","icon":"list-checks","body":"Your primary category is wrong, or the secondary ones were never set. Categories decide which searches you are eligible for at all."},{"title":"Inconsistent Information","icon":"warning","body":"Your name, address or phone number disagrees with what other listings say. Search engines notice the disagreement even when customers do not."},{"title":"No Recent Activity","icon":"calendar","body":"Your profile has not been posted to in months. An inactive profile reads as an inactive business."},{"title":"Unanswered Reviews","icon":"message-square","body":"Reviews sitting without a reply, good ones as well as bad. The reply is read by everyone who arrives afterwards."},{"title":"Missing Services","icon":"file-text","body":"Your services and products are undefined, so the profile cannot match a search for something you genuinely do."},{"title":"No Visibility Tracking","icon":"search","body":"You have no way of knowing whether any of it is working, or where in your area you are visible and where you are not."}]}'::jsonb, 2 from public.pages where slug = '/google-business-profile-optimization';
insert into public.sections (page_id, key, type, tone, data, position) select id, 'free-audit', 'auditForm', NULL, '{"eyebrow":"Free Visibility Audit","heading":"Get a Free Look at Your Profile","body":"A written audit of the profile and the site behind it, built on the same four headings as the monthly recap: what is there, why it matters, what is working and what is not, and what to do next.","covers":["Categories, services and business information","Listing consistency across the web","Profile activity, photos and reviews","Where the profile is visible across the service area"],"note":"No call required.","submitLabel":"Get a Free Visibility Audit","profileHelp":"Optional. Paste the map listing link if you have it handy.","source":"Free Visibility Audit"}'::jsonb, 3 from public.pages where slug = '/google-business-profile-optimization';
insert into public.sections (page_id, key, type, tone, data, position) select id, 'what-jmc-does', 'cardGrid', 'surface', '{"variant":"cards","columns":3,"eyebrow":"The Work","heading":"What JMC Does to a Profile","body":"Three things once, and three things every month. Which of the two you need is the whole of the choice below.","groupLabels":[{"at":0,"label":"One-time foundation"},{"at":3,"label":"Ongoing every month"}],"cards":[{"title":"Profile Audit","icon":"clipboard-check","body":"A full review of the profile as it stands, against how people in your area actually search for what you do."},{"title":"Category & Services Setup","icon":"list-checks","body":"Primary and secondary categories set deliberately, with services and products defined so the profile can match real searches."},{"title":"NAP & Citation Consistency","icon":"shield-check","body":"Name, address and phone standardised, then corrected across the listings that carry an older version of them."},{"title":"Ongoing Profile Posts","icon":"pencil","body":"Regular posts through the month, so the profile stays active rather than going quiet after the setup work finishes."},{"title":"Review Requests & Replies","icon":"star","body":"Requests sent to real customers and replies written to what arrives, positive and negative alike. Nothing is fabricated or incentivised."},{"title":"Local Search Grid Tracking","icon":"map-pin","body":"Visibility measured across the service area rather than as one blended number, so you can see where the profile is strong and where it is not.","visual":"searchGrid"}]}'::jsonb, 4 from public.pages where slug = '/google-business-profile-optimization';
insert into public.sections (page_id, key, type, tone, data, position) select id, 'two-ways', 'cardGrid', 'white', '{"variant":"cards","columns":2,"eyebrow":"Two Ways In","heading":"One-Time Setup, or Ongoing Management","body":"The foundation work can be bought once on its own. The monthly work only makes sense as an ongoing engagement.","cards":[{"title":"One-Time Setup","icon":"rocket","meta":"Neighborhood Launch Sprint, $799","body":"Completed within 30 days. Covers the profile audit and core optimization, a citation audit and a single standard for your business information, and a 30-day roadmap for the whole picture rather than the profile alone. Start monthly service within 30 days and the onboarding fee on any Local package is waived.","cta":{"label":"View Launch Sprints","href":"/launch-sprints"}},{"title":"Ongoing Management","icon":"layers","meta":"Local SEO packages, from $875 a month","body":"Monthly profile posts, review requests and replies, citation work, local search grid tracking, and the monthly recap that says what changed. The profile work sits inside the wider local engagement rather than beside it.","cta":{"label":"Explore Local SEO","href":"/local-seo-services"}}],"cta":{"label":"Request a Visibility Review","href":"/contact"}}'::jsonb, 5 from public.pages where slug = '/google-business-profile-optimization';
insert into public.sections (page_id, key, type, tone, data, position) select id, 'monthly-recap', 'reportingBlock', 'surface', '{"eyebrow":"Reporting","heading":"The Monthly Recap","body":"Profile work is easy to do invisibly, which is exactly why it gets reported the same way as everything else.","did":"The posts published, the listings corrected, the reviews replied to, named individually.","why":"Why that work was the priority, and what it was expected to affect.","changed":"Grid visibility across the service area, compared with last month, including the quiet ones.","next":"What is queued for the coming month, written down before it starts.","cta":{"label":"See How JMC Reports SEO Progress","href":"/seo-reporting"}}'::jsonb, 6 from public.pages where slug = '/google-business-profile-optimization';
insert into public.sections (page_id, key, type, tone, data, position) select id, 'faq', 'faq', 'white', '{"eyebrow":"Questions","heading":"Profile Questions","items":[{"question":"Is this the same as Google My Business?","answer":"Yes. Google renamed Google My Business to Google Business Profile, and a lot of people still search for the old name. It is the same listing and the same work."},{"question":"Can this be done without a monthly package?","answer":"Yes. The Neighborhood Launch Sprint covers the foundation work as a one-time engagement and finishes with a 30-day roadmap, with no obligation to continue into a monthly package afterwards."},{"question":"How long before the profile improves?","answer":"Some changes show up almost immediately: corrected categories, services, hours and information can be reflected within days. Movement in map rankings is slower and depends on how competitive your area is, which is why the reporting separates the two rather than blending them."},{"question":"Who owns the profile?","answer":"You do, always. JMC requests manager access to a profile you own and never takes ownership of one. If the engagement ends, access is removed and nothing has to be handed back, because it was never held."},{"question":"Can suspended or duplicate profiles be fixed?","answer":"Duplicates can usually be merged or removed. Suspensions vary: some are caused by fixable information problems and some are not, and nobody can promise reinstatement. What JMC will do is look at the cause honestly and tell you whether it is worth pursuing."},{"question":"Does this help a business with no storefront?","answer":"Yes. A service-area business hides its address and is ranked against the area it covers, which makes categories, service definitions and listing consistency do more of the work. JMC is a service-area business itself and does not publish a street address."}],"cta":{"label":"Get a Free Visibility Audit","href":"#free-audit"}}'::jsonb, 7 from public.pages where slug = '/google-business-profile-optimization';
insert into public.sections (page_id, key, type, tone, data, position) select id, 'final-cta', 'finalCta', NULL, '{"heading":"Start With the Profile","body":"A visibility review covers the profile, the site behind it, and which of the two is holding the other back.","primaryCta":{"label":"Request a Visibility Review","href":"/contact"},"secondaryCta":{"label":"View Launch Sprints","href":"/launch-sprints"}}'::jsonb, 8 from public.pages where slug = '/google-business-profile-optimization';
insert into public.sections (page_id, key, type, tone, data, position) select id, 'hero', 'heroSplit', NULL, '{"eyebrow":"SEO Reporting","heading":"SEO Reporting That Answers Four Questions","body":"Most SEO reporting either buries the work in numbers or skips it entirely. JMC reports every month in the same shape, so you always know what was done, why it was the priority, and what it changed.","primaryCta":{"label":"Request a Visibility Review","href":"/contact"},"secondaryCta":{"label":"Explore Local SEO","href":"/local-seo-services"},"showcase":[{"kind":"report","label":"Every month","title":"Monthly Project Recap","items":["What We Did","Why We Did It","What Changed","Where We''re Headed"]},{"kind":"coverage","label":"Also included","title":"Quarterly Update","items":["Local","Traditional","Every tier"]}]}'::jsonb, 0 from public.pages where slug = '/seo-reporting';
insert into public.sections (page_id, key, type, tone, data, position) select id, 'four-questions', 'fourQuestions', 'surface', '{"eyebrow":"The Shape of It","heading":"The Four Questions Every Recap Answers","body":"The same four headings every month, in the same order, on every package in both service lines.","did":"The actual work completed that month, listed as specific tasks rather than categories. Not “content optimization” but which pages were rewritten, which titles changed, and which listings were corrected.","didExample":"Rewrote service page titles and meta descriptions for four priority pages.","why":"The reasoning behind the order. SEO is a queue of things worth doing, and the useful part of a report is understanding why this month''s work went to the front of it rather than something else.","whyExample":"Those four pages already had impressions and no clear title, so they were the cheapest movement available.","changed":"Movement, reported honestly. Some months show clear change and some show very little, and the recap says which one it was. A report that reads like progress every single month is not a report.","changedExample":"Grid visibility for the primary service term, compared with last month.","next":"Next month''s priorities, written down before the month starts, so nothing in the following recap is a surprise. It also gives you somewhere to push back before the work happens rather than after.","nextExample":"Next: the two service pages with no dedicated content, then a citation audit."}'::jsonb, 1 from public.pages where slug = '/seo-reporting';
insert into public.sections (page_id, key, type, tone, data, position) select id, 'example', 'recapExample', 'white', '{"eyebrow":"An Example","heading":"What a Recap Actually Looks Like","body":"The structure, drawn out. Every line below describes the kind of thing a recap contains.","panelTitle":"Monthly Project Recap","panelMeta":"Structure only. Not a real client report.","did":["Rewrote titles and meta descriptions for four priority service pages.","Corrected the business category and service list on the Google Business Profile.","Published one strategic SEO page for the highest-intent service term."],"why":["Those four pages already had impressions with no clear title, so they were the cheapest movement available.","The profile category was narrower than the services actually offered, which limits which searches it can appear for."],"changed":["Grid visibility for the primary service term, compared with last month.","Movement on the tracked keyword set, with the ones that moved named individually.","Where the month was quiet, the recap says so and says why."],"next":["The two service pages with no dedicated content.","A citation audit across the listings that carry an old address."],"caption":"An example of the structure, not a real client report. No figures appear in it because none of them would be real, and a page about honest reporting is the worst possible place for an invented number."}'::jsonb, 2 from public.pages where slug = '/seo-reporting';
insert into public.sections (page_id, key, type, tone, data, position) select id, 'deliverables', 'cardGrid', 'surface', '{"variant":"cards","columns":3,"eyebrow":"What Arrives","heading":"What Arrives, and When","body":"Three deliverables, included in every package in both service lines.","cards":[{"title":"Monthly Reporting","icon":"bar-chart","body":"Detailed reporting on the work and the tracked keyword and competitor set. Traditional SEO packages add dashboard reporting on top of it."},{"title":"Monthly Project Recap","icon":"message-square","body":"Delivered by Loom or a video call. A person walking through what happened and answering questions, rather than a file dropped into an inbox."},{"title":"Quarterly Project Update","icon":"calendar","body":"A wider look every three months: what the quarter changed, what it taught, and where the next one is pointed."}]}'::jsonb, 3 from public.pages where slug = '/seo-reporting';
insert into public.sections (page_id, key, type, tone, data, position) select id, 'standards', 'cardGrid', 'white', '{"variant":"numbered","columns":3,"eyebrow":"Editorial Discipline","heading":"What Gets Left Out","body":"A recap is more useful for what it leaves out than for what it piles in.","cards":[{"title":"Fewer Numbers, Better Ones","body":"A figure earns its place by informing a decision. Metrics that look impressive without changing what happens next are left out on purpose."},{"title":"Every Number Has a Reason","body":"Nothing appears in a recap without an explanation of why it is there and what it means. A number with no reading is decoration."},{"title":"Honest in Slow Months","body":"SEO has quiet months. When one happens, the recap says so, says why, and says what is being done about it."}]}'::jsonb, 4 from public.pages where slug = '/seo-reporting';
insert into public.sections (page_id, key, type, tone, data, position) select id, 'by-lane', 'cardGrid', 'surface', '{"variant":"cards","columns":2,"eyebrow":"By Service","heading":"Reporting Differs by Where You Compete","body":"The four questions are the same in both lanes. What sits underneath them is not.","cards":[{"title":"Local SEO","icon":"map-pin","body":"Local search grid tracking, profile activity, review movement, and citation consistency. Visibility mapped across the service area rather than reduced to a single blended rank.","cta":{"label":"Explore Local SEO","href":"/local-seo-services"}},{"title":"Traditional SEO","icon":"globe","body":"Dashboard reporting, tracked keywords and competitors across markets, technical issues flagged as they appear, and how the strategic pages are performing.","cta":{"label":"Explore Traditional SEO","href":"/traditional-seo-services"}}]}'::jsonb, 5 from public.pages where slug = '/seo-reporting';
insert into public.sections (page_id, key, type, tone, data, position) select id, 'faq', 'faq', 'white', '{"eyebrow":"Questions","heading":"Reporting Questions","items":[{"question":"How often do reports arrive?","answer":"A recap every month and a project update every quarter. Both are included in every package in both service lines, at every tier."},{"question":"Is the recap a document or a call?","answer":"A Loom video or a live video call, whichever suits you. Either way a person walks through the work rather than sending a file and hoping it gets read. Written reporting comes alongside it."},{"question":"What happens in a month where little moves?","answer":"The recap says so, and says why. SEO does not move in a straight line, and a report that reads like progress every single month is telling you less than one that admits a quiet stretch."},{"question":"Are rankings guaranteed?","answer":"No, and anyone guaranteeing them is guessing. What is guaranteed is the scope, the reporting, and knowing exactly what was done and why."},{"question":"Who else can see the reports?","answer":"Your call. The recap and the reporting are yours to share internally with whoever needs them, and the video format tends to make that easier rather than harder."},{"question":"What tools are used?","answer":"A mix of rank and grid tracking, Google Search Console, Google Analytics, and technical crawling. The tools matter less than the reading of them, which is the part the recap is for."}],"cta":{"label":"Request a Visibility Review","href":"/contact"}}'::jsonb, 6 from public.pages where slug = '/seo-reporting';
insert into public.sections (page_id, key, type, tone, data, position) select id, 'final-cta', 'finalCta', NULL, '{"heading":"See What the First Report Would Say","body":"A visibility review covers where you appear now, what is holding it back, and which of those is worth acting on first.","primaryCta":{"label":"Request a Visibility Review","href":"/contact"},"secondaryCta":{"label":"View Monthly SEO Packages","href":"/monthly-seo-packages"}}'::jsonb, 7 from public.pages where slug = '/seo-reporting';
